import { LogService } from "@bitwarden/common/platform/abstractions/log.service";
import { PlatformUtilsService } from "@bitwarden/common/platform/abstractions/platform-utils.service";
import { SdkLoadService } from "@bitwarden/common/platform/abstractions/sdk/sdk-load.service";
import { IpcService } from "@bitwarden/common/platform/ipc";
import {
  IncomingMessage,
  IpcClient,
  IpcCommunicationBackend,
  ipcRegisterDiscoverHandler,
  OutgoingMessage,
} from "@bitwarden/sdk-internal";

import { BrowserBackgroundIpcTransport } from "./transports";

/**
 * {@link IpcService} for extension pages (popup, popout, sidebar). All traffic goes to the
 * background, which addresses this page as `BrowserForeground { id }`.
 */
export class IpcForegroundService extends IpcService {
  private communicationBackend?: IpcCommunicationBackend;

  constructor(
    private platformUtilsService: PlatformUtilsService,
    private logService: LogService,
  ) {
    super();
  }

  override async init() {
    try {
      // This function uses classes and functions defined in the SDK, so we need to wait for the SDK to load.
      await SdkLoadService.Ready;

      const transport = new BrowserBackgroundIpcTransport((message: IncomingMessage) =>
        this.communicationBackend?.receive(message),
      );

      this.communicationBackend = new IpcCommunicationBackend({
        send: (message: OutgoingMessage) => transport.send(message),
      });

      await super.initWithClient(IpcClient.newWithSdkInMemorySessions(this.communicationBackend));

      await ipcRegisterDiscoverHandler(this.client, {
        version: await this.platformUtilsService.getApplicationVersion(),
      });

      // Connect once the client and its handlers are ready, so the background can reach this
      // page, e.g. through broadcasts, before it sends anything.
      transport.init();
    } catch (e) {
      this.logService.error("[IPC] Initialization failed", e);
    }
  }
}
